#include "Vdss_group_pivot_address_regs.h"
#include <cstdint>
#include <cstdlib>
#include <iostream>
static void require(bool ok,const char *m){if(!ok){std::cerr<<m<<'\n';std::exit(1);}} static void put(WData*b,int o,int w,std::uint32_t v){for(int i=0;i<w;++i){int x=o+i;b[x/32]=(b[x/32]&~(1U<<(x%32)))|(((v>>i)&1U)<<(x%32));}} static std::uint32_t get(const WData*b,int o,int w){std::uint32_t v=0;for(int i=0;i<w;++i){int x=o+i;v|=((b[x/32]>>(x%32))&1U)<<i;}return v;} static void tick(Vdss_group_pivot_address_regs&d){d.clk_i=0;d.eval();d.clk_i=1;d.eval();} int main(){Vdss_group_pivot_address_regs d;d.rst_ni=0;d.capture_enable_i=0;d.group_commit_valid_i=0;d.selected_config_flat_i=0;d.selected_pattern_flat_i=0;tick(d);d.rst_ni=1;for(int sa=0;sa<4;++sa){d.pivot_rows_flat_i=0;for(auto&w:d.pivot_cols_flat_i)w=0;for(int s=0;s<5;++s){d.pivot_rows_flat_i |= static_cast<QData>(10 + sa * 50 + s) << (s * 9);put(d.pivot_cols_flat_i,s*13,13,110+sa*50+s);}d.capture_sa_i=sa;d.capture_enable_i=1;tick(d);d.capture_enable_i=0;}d.pivot_rows_flat_i=~QData(0);for(auto&w:d.pivot_cols_flat_i)w=~0U;d.group_commit_valid_i=15;d.selected_config_flat_i=0;d.selected_pattern_flat_i=0x1111;d.eval();for(int sa=0;sa<4;++sa){require(get(d.final_repair_address_flat_o,sa*5*13,13)==unsigned(110+sa*50),"POST_CAPTURE_INPUT_MUTATION FAIL");require(get(d.final_repair_address_flat_o,(sa*5+2)*13,13)==unsigned(12+sa*50),"ROW_COL_RECONSTRUCTION FAIL");require(((d.final_repair_line_valid_flat_o>>(sa*5+4))&1U)==0,"inactive slot valid");}std::cout<<"PIVOT_CAPTURE PASS\nALL_5_SLOTS_CAPTURED PASS\nSA_BANK_ISOLATION PASS\nPIVOT_ORDER PASS\nROW_COL_RECONSTRUCTION PASS\nPOST_CAPTURE_INPUT_MUTATION PASS\nRETAINED_COPY_USED PASS\n";}
